function sharesArea(rec1: number[], rec2: number[]): boolean {
  const width = Math.min(rec1[2], rec2[2]) - Math.max(rec1[0], rec2[0]);
  const height = Math.min(rec1[3], rec2[3]) - Math.max(rec1[1], rec2[1]);
  return width > 0 && height > 0;
}

